WITH ss_joined AS (SELECT ss.ss_store_sk, s.s_store_name, ss.ss_sold_date_sk, ss.ss_net_paid_inc_tax, ss.ss_net_profit, ss.ss_ext_discount_amt, p.p_promo_id FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk LEFT JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk), daily_agg AS (SELECT ss_store_sk, s_store_name, ss_sold_date_sk, SUM(ss_net_profit) AS daily_net_profit, AVG(ss_ext_discount_amt) AS avg_discount, COUNT(*) AS transaction_cnt FROM ss_joined GROUP BY ss_store_sk, s_store_name, ss_sold_date_sk), ranked AS (SELECT da.ss_store_sk, da.s_store_name, da.ss_sold_date_sk, da.daily_net_profit, da.avg_discount, da.transaction_cnt, ROW_NUMBER() OVER (PARTITION BY da.ss_sold_date_sk ORDER BY da.daily_net_profit DESC) AS daily_profit_rank FROM daily_agg da) SELECT * FROM ranked WHERE daily_profit_rank <= 3 ORDER BY ss_sold_date_sk, daily_profit_rank
